/// <summary>
/// CB705_VendorRebatesPosting
/// </summary>
[ExtensionOf(classStr(TAMRebateDatePeriod))]
final class METTAMRebateDatePeriod_Extension
{
    private METInvoiceConsolidationByRebateType consolidationByRebateType;
    private METVendorRebateTypeId               vendorRebateTypeId;
    private TAMRebateParameters                 rebateParameters; 
    private TAMRebateTransactionType            transactionType;

}

Method.Source:
/// <summary>
/// Parm method for the rebate transaction type
/// </summary>
/// <param name = "_transactionType"><c>TAMRebateTransactionType</c></param>
/// <returns><c>TAMRebateTransactionType</c></returns>
public TAMRebateTransactionType metParmRebateTransactionType(TAMRebateTransactionType _transactionType = transactionType)
{
    transactionType = _transactionType;
    return transactionType;
}

/// <summary>
/// Initialise vendorRebateTypeId and consolidationByRebateType
/// </summary>
/// <param name = "_rebateDate">Rebate date</param>
/// <param name = "_rebatePerFieldId">Rebate per field id</param>
/// <param name = "_periodTypeIdFieldId">Period typeId fieldId</param>
protected void initializeFromRebateDate(TAMRebateDate _rebateDate, FieldId _rebatePerFieldId, FieldId _periodTypeIdFieldId)
{
    next initializeFromRebateDate(_rebateDate, _rebatePerFieldId, _periodTypeIdFieldId);

    rebateParameters = TAMRebateParameters::find();

    TAMRebateTable rebateTable = TAMRebateTable::find(_rebateDate.RebateId);
    vendorRebateTypeId = rebateTable.METVendRebateTypeId;

    TAMRebateDeal rebateDeal = TAMRebateDeal::find(rebateTable.RebateDeal);
    consolidationByRebateType = rebateDeal.METInvoiceConsolidationByRebateType;
}

/// <summary>
/// Adding vendorRebateTypeId in the mapKey
/// </summary>
/// <param name = "_fromDate">From date</param>
/// <param name = "_toDate">To date</param>
/// <param name = "_rebateRefId">Rebate ref id</param>
/// <returns>mapKey container</returns>
protected container getRebateTransIdMapKey(FromDate _fromDate, ToDate _toDate, TAMRebateRefId _rebateRefId)
{
    container con = next getRebateTransIdMapKey(_fromDate, _toDate, _rebateRefId);

    if (transactionType ==TAMRebateTransactionType::Rebate
    &&  rebateParameters.METProcessVendRebateBasedVendRebType
    &&  consolidationByRebateType)
    {
        return [_fromDate, _toDate, vendorRebateTypeId];
    }

    return con;
}

/// <summary>
/// CB705_VendorRebatePosting moving extension now that method is public
/// When an instance of TAMRebateDatePeriod is created, this method will set the TAMRebateTransactionType
/// So we can update the RebateTransIdMapKey to add vendorRebateTypeId only in the rebate transaction type scenario TAMRebateDatePeriod\getRebateTransIdMapKey.
/// </summary>
/// <param name = "_instance">Instance of <c>TAMRebateDatePeriod</c></param>
/// <param name = "_transactionType">Rebate transaction type</param>
/// <returns>Instance of <c>TAMRebateDatePeriod</c> set with the TAMRebateTransactionType</returns>
public static TAMRebateDatePeriod newFromRebateDateAndTransactionType(TAMRebateDate _rebateDate, TAMRebateTransactionType _transactionType)
{
    TAMRebateDatePeriod rebateDatePeriod = next newFromRebateDateAndTransactionType(_rebateDate, _transactionType);
    rebateDatePeriod.metParmRebateTransactionType(_transactionType);

    return rebateDatePeriod;
}

public TAMRebateDateTrans getRebateDateTransForTransId( FromDate _fromDate, ToDate _toDate, TAMRebateRefAccount _account, TAMRebateTransactionType _rebateTransactionType, RecId _dealRecId, TAMRebateId _rebateId, str _aggregatedStr) { TAMRebateDateTrans dateTrans = next getRebateDateTransForTransId( _fromDate, _toDate, _account, _rebateTransactionType, _dealRecId, _rebateId, _aggregatedStr);
if (_aggregatedStr == '') { return dateTrans; }
select firstonly RebateTransId from dateTrans where dateTrans.RebateFromDate == _fromDate && dateTrans.RebateToDate == _toDate && dateTrans.RemittanceAccount == _account && dateTrans.RebateTransactionType == _rebateTransactionType && dateTrans.RebateDeal == _dealRecId && dateTrans.RebateId == _rebateId && dateTrans.RebatePosted == NoYes::No && dateTrans.METAggregatedStr == _aggregatedStr; // New condition for aggregation string
return dateTrans; }

/// <summary>
/// CB201 - Get rebate transaction ids with aggregator value
/// </summary>
/// <param name = "_fromDate">Calculation from date</param>
/// <param name = "_toDate">Calculation to date</param>
/// <param name = "_rebateRefId">Rebate reference id</param>
/// <param name = "_aggregatedStr">Aggregatore value</param>
/// <returns>Rebate transaction id</returns>
public TAMRebateTransId getRebateTransIdWithAggregation(FromDate _fromDate, ToDate _toDate, TAMRebateRefId _rebateRefId, str _aggregatedStr = '')
{
    if (prmIsDefault(_aggregatedStr) || _aggregatedStr == '')
    {
        return this.getRebateTransId(_fromDate, _toDate, _rebateRefId);
    }

    container mapKey = this.getRebateTransIdMapKeyWithAggregation(_fromDate, _toDate, _rebateRefId, _aggregatedStr);
    TAMRebateTransId rebateTransId = this.getRebateTransIdFromMap(mapKey);
    return rebateTransId;
}

/// <summary>
/// CB201 - Get rebate transaction ids and key map with aggregator value
/// </summary>
/// <param name = "_fromDate">Calculation from date</param>
/// <param name = "_toDate">Calculation to date</param>
/// <param name = "_rebateRefId">Rebate reference id</param>
/// <param name = "_aggregatedStr">Aggregatore value</param>
/// <returns>container with from date, to date and aggregator value</returns>
public container getRebateTransIdMapKeyWithAggregation(FromDate _fromDate, ToDate _toDate, TAMRebateRefId _rebateRefId, str _aggregatedStr = '')
{
    if (prmIsDefault(_aggregatedStr) || _aggregatedStr == '')
    {
        return this.getRebateTransIdMapKey(_fromDate, _toDate, _rebateRefId);
    }

    // Add aggregation string to the map key
    return [_fromDate, _toDate, _aggregatedStr];
}

/// <summary>
/// CB201 - Get rebate transaction ids with aggregator value
/// </summary>
/// <param name = "_fromDate">Calculation from date</param>
/// <param name = "_toDate">Calculation to date</param>
/// <param name = "_account">Rebate refrence account</param>
/// <param name = "_dealRecId">Rebate deal record id</param>
/// <param name = "_rebateId">Rebate reference id</param>
/// <param name = "_aggregatedStr">Aggregatore value</param>
/// <returns>Data container</returns>
protected container getRebateTransIdMapKeyWithCustomerAndAggregation(
    FromDate            _fromDate,
    ToDate              _toDate,
    TAMRebateRefAccount _account,
    RecId               _dealRecId,
    TAMRebateId         _rebateId,
    str                 _aggregatedStr = '')
{
    if (prmIsDefault(_aggregatedStr) || _aggregatedStr == '')
    {
        return this.getRebateTransIdMapKeyWithCustomer(_fromDate, _toDate, _account, _dealRecId, _rebateId);
    }

    // Add aggregation string to the map key
    return [_fromDate, _toDate, _account, _dealRecId, _rebateId, _aggregatedStr];
}

/// <summary>
/// Add rebate transaction to map
/// </summary>
/// <param name = "_fromDate">Calculation from date</param>
/// <param name = "_toDate">Calculation to date</param>
/// <param name = "_rebateRefId">Rebate reference id</param>
/// <param name = "_rebateTransId">Rebate transaction refrence id</param>
/// <param name = "_aggregatedStr">Aggregator value</param>
public void addRebateTransId(FromDate _fromDate, ToDate _toDate, TAMRebateRefId _rebateRefId, TAMRebateTransId _rebateTransId, str _aggregatedStr)
{
    if (_aggregatedStr == '')
    {
        next addRebateTransId(_fromDate, _toDate, _rebateRefId, _rebateTransId);
        return;
    }
    else
    {
        rebateTransIdMap.insert(this.getRebateTransIdMapKeyWithAggregation(_fromDate, _toDate, _rebateRefId, _aggregatedStr), _rebateTransId);
    }
}

/// <summary>
/// Get rebate transaction id with customer and aggregation
/// </summary>
/// <param name = "_fromDate">Calculation from date</param>
/// <param name = "_toDate">Calculation to date</param>
/// <param name = "_account">Rebate account</param>
/// <param name = "_rebateTransactionType">Rebate transaction type</param>
/// <param name = "_dealRecId">Rebate deal record id</param>
/// <param name = "_rebateId">Rebate id</param>
/// <param name = "_aggregatedStr">Aggregator value</param>
/// <returns>Rebate transaction id</returns>
public TAMRebateTransId getRebateTransIdWithCustomerAndAggregation(
    FromDate                    _fromDate,
    ToDate                      _toDate,
    TAMRebateRefAccount         _account,
    TAMRebateTransactionType    _rebateTransactionType,
    RecId                       _dealRecId,
    TAMRebateId                 _rebateId,
    str                         _aggregatedStr = '')
{
    if (prmIsDefault(_aggregatedStr) || _aggregatedStr == '')
    {
        return this.getRebateTransIdWithCustomer(_fromDate, _toDate, _account, _rebateTransactionType, _dealRecId, _rebateId);
    }

    container mapKey = this.getRebateTransIdMapKeyWithCustomerAndAggregation(_fromDate, _toDate, _account, _dealRecId, _rebateId);
    TAMRebateTransId rebateTransId = this.getRebateTransIdFromMapWithCustomer(mapKey, _fromDate, _toDate, _account, _rebateTransactionType, _dealRecId, _rebateId, _aggregatedStr);
    return rebateTransId;
}
